import { makeCtx } from "./ctx";
import type { Actor } from "./domain";
import { type Db, emptyDb } from "./db/rows";
import { createFairnessCase, transitionCase } from "./services/cases";
import { submitFeedback, submitSafetyIncident } from "./services/reports";
import { endShift, startShift } from "./services/shifts";
import { reconcileDay } from "./services/wages";
import { updateSkillPassport } from "./services/skills";

// Synthetic, deterministic demo data for both industries. No real people. The same data feeds the
// in-memory demo store and supabase/seed.sql (generated by `npm run db:seed-sql`), so IDs match.

/** Readable fixed UUIDs: group = entity kind, n = index. */
const u = (group: number, n: number) =>
  `${group.toString(16).padStart(8, "0")}-0000-4000-8000-${n.toString(16).padStart(12, "0")}`;

export const SEED = {
  orgConstruction: u(1, 1),
  orgCollege: u(1, 2),
  construction: {
    admin: u(2, 1), supervisor: u(2, 2), murugan: u(2, 3), selvi: u(2, 4), karthik: u(2, 5),
    site: u(3, 1), skillElectrical: u(8, 1), skillMasonry: u(8, 2),
  },
  college: {
    admin: u(2, 11), supervisor: u(2, 12), rajesh: u(2, 13), meena: u(2, 14), anwar: u(2, 15),
    site: u(3, 2), skillPlumbing: u(8, 11), skillElectrical: u(8, 12),
  },
} as const;

type Seq = { n: number };
const idGen = (seq: Seq) => () => u(9, ++seq.n);

/** IST wall-clock to an ISO instant. */
const ist = (date: string, hhmm: string) => new Date(Date.parse(`${date}T${hhmm}:00+05:30`));

function base(db: Db) {
  db.industry_configs.push(
    {
      id: "construction", label: "Construction", max_safe_hours_per_day: 10,
      shift_patterns: [{ name: "Day", start: "07:00", end: "16:00" }, { name: "Extended", start: "07:00", end: "19:00" }],
      safety_categories: ["fall_hazard", "scaffolding", "electrical", "ppe_missing", "heavy_machinery", "other"],
    },
    {
      id: "college", label: "College facilities", max_safe_hours_per_day: 11,
      shift_patterns: [{ name: "Morning", start: "06:00", end: "14:00" }, { name: "Evening", start: "14:00", end: "22:00" }],
      safety_categories: ["electrical", "slip_hazard", "chemical_cleaning", "plumbing_leak", "kitchen", "other"],
    },
  );
  db.organisations.push(
    { id: SEED.orgConstruction, name: "Demo Tower Constructions", industry_id: "construction" },
    { id: SEED.orgCollege, name: "Demo Campus Facilities", industry_id: "college" },
  );
  db.worksites.push(
    { id: SEED.construction.site, org_id: SEED.orgConstruction, name: "Tower Site A" },
    { id: SEED.college.site, org_id: SEED.orgCollege, name: "Main Campus" },
  );
  const areas: [string, string, string, number][] = [
    [SEED.orgConstruction, SEED.construction.site, "Scaffolding", 1], [SEED.orgConstruction, SEED.construction.site, "Mixing yard", 2],
    [SEED.orgConstruction, SEED.construction.site, "Material store", 3], [SEED.orgConstruction, SEED.construction.site, "Site office", 4],
    [SEED.orgCollege, SEED.college.site, "Hostel block", 5], [SEED.orgCollege, SEED.college.site, "Lab building", 6],
    [SEED.orgCollege, SEED.college.site, "Canteen", 7], [SEED.orgCollege, SEED.college.site, "Maintenance room", 8],
  ];
  for (const [org_id, worksite_id, name, n] of areas) db.work_areas.push({ id: u(4, n), org_id, worksite_id, name });

  const roles: [string, string, number, number][] = [
    [SEED.orgConstruction, "Mason", 90, 1], [SEED.orgConstruction, "Helper", 65, 2], [SEED.orgConstruction, "Electrician", 110, 3],
    [SEED.orgCollege, "Plumber", 100, 4], [SEED.orgCollege, "Housekeeping", 70, 5], [SEED.orgCollege, "Electrician", 115, 6],
  ];
  for (const [org_id, name, base_hourly_rate, n] of roles) db.job_roles.push({ id: u(5, n), org_id, name, base_hourly_rate });

  db.pay_rules.push(
    { id: u(6, 1), org_id: SEED.orgConstruction, name: "Construction standard", effective_from: "2026-01-01", regular_hours_per_day: 8, overtime_multiplier: 2, discrepancy_tolerance: 1 },
    { id: u(6, 2), org_id: SEED.orgCollege, name: "Campus standard", effective_from: "2026-01-01", regular_hours_per_day: 8, overtime_multiplier: 1.5, discrepancy_tolerance: 1 },
  );

  const c = SEED.construction, k = SEED.college;
  const people: [string, string, "worker" | "supervisor" | "employer_admin", string, string][] = [
    [c.admin, SEED.orgConstruction, "employer_admin", "Demo Admin (Construction)", "admin.construction@demo.invalid"],
    [c.supervisor, SEED.orgConstruction, "supervisor", "Demo Supervisor (Construction)", "sup.construction@demo.invalid"],
    [c.murugan, SEED.orgConstruction, "worker", "Murugan", "murugan@demo.invalid"],
    [c.selvi, SEED.orgConstruction, "worker", "Selvi", "selvi@demo.invalid"],
    [c.karthik, SEED.orgConstruction, "worker", "Karthik", "karthik@demo.invalid"],
    [k.admin, SEED.orgCollege, "employer_admin", "Demo Admin (College)", "admin.college@demo.invalid"],
    [k.supervisor, SEED.orgCollege, "supervisor", "Demo Supervisor (College)", "sup.college@demo.invalid"],
    [k.rajesh, SEED.orgCollege, "worker", "Rajesh", "rajesh@demo.invalid"],
    [k.meena, SEED.orgCollege, "worker", "Meena", "meena@demo.invalid"],
    [k.anwar, SEED.orgCollege, "worker", "Anwar", "anwar@demo.invalid"],
  ];
  for (const [id, org_id, role, display_name, email] of people) {
    db["auth.users"].push({ id, email });
    db.profiles.push({ id, org_id, role, display_name, preferred_language: "en" });
  }
  const workers: [string, string, string, string, string, number][] = [
    [c.murugan, SEED.orgConstruction, u(5, 1), c.site, c.supervisor, 90],
    [c.selvi, SEED.orgConstruction, u(5, 2), c.site, c.supervisor, 65],
    [c.karthik, SEED.orgConstruction, u(5, 3), c.site, c.supervisor, 110],
    [k.rajesh, SEED.orgCollege, u(5, 4), k.site, k.supervisor, 100],
    [k.meena, SEED.orgCollege, u(5, 5), k.site, k.supervisor, 70],
    [k.anwar, SEED.orgCollege, u(5, 6), k.site, k.supervisor, 115],
  ];
  for (const [profile_id, org_id, job_role_id, worksite_id, supervisor_id, hourly_rate] of workers) {
    db.worker_profiles.push({ profile_id, org_id, job_role_id, worksite_id, supervisor_id, hourly_rate });
  }

  db.skills.push(
    { id: c.skillElectrical, org_id: SEED.orgConstruction, name: "Electrical wiring" },
    { id: c.skillMasonry, org_id: SEED.orgConstruction, name: "Masonry" },
    { id: k.skillPlumbing, org_id: SEED.orgCollege, name: "Plumbing" },
    { id: k.skillElectrical, org_id: SEED.orgCollege, name: "Electrical wiring" },
  );
  db.training_records.push(
    { id: u(10, 1), org_id: SEED.orgConstruction, worker_id: c.karthik, skill_id: c.skillElectrical, title: "Site electrical safety course", completed_at: "2026-02-10", verified_by: c.supervisor },
    { id: u(10, 2), org_id: SEED.orgCollege, worker_id: k.rajesh, skill_id: k.skillPlumbing, title: "Pipe fitting certification", completed_at: "2026-01-20", verified_by: k.supervisor },
  );
  db.scenario_definitions.push(
    { id: u(11, 1), org_id: null, industry_id: "construction", name: "Unpaid overtime on a long scaffold day", definition: { steps: ["long_shift", "payroll_short", "worker_files_case"] } },
    { id: u(11, 2), org_id: null, industry_id: "college", name: "Hostel maintenance overrun", definition: { steps: ["long_shift", "payroll_short", "worker_files_case"] } },
  );
}

/** Build the full synthetic dataset by running the real services under a fixed clock. */
export function buildSeedDb(): Db {
  const db = emptyDb();
  base(db);
  const seq: Seq = { n: 0 };
  const id = idGen(seq);
  let clock = ist("2026-03-02", "07:00");
  const as = (userId: string, orgId: string, role: Actor["role"]) =>
    makeCtx(db, { userId, orgId, role, kind: "human" }, { now: () => clock, id });

  const c = SEED.construction, k = SEED.college;
  const oc = SEED.orgConstruction, ok = SEED.orgCollege;

  // Construction: Murugan works 12h (over the 10h safe limit) and reports being paid for 8h only.
  startShift(as(c.murugan, oc, "worker"), {});
  clock = ist("2026-03-02", "19:00");
  endShift(as(c.murugan, oc, "worker"), {});
  const r1 = reconcileDay(as(c.murugan, oc, "worker"), { workerId: c.murugan, date: "2026-03-02", amountPaid: 720, source: "worker_reported" });
  const case1 = createFairnessCase(as(c.murugan, oc, "worker"), {
    caseType: "wage_discrepancy", title: "Overtime not paid on 2 March",
    summary: "Worked 07:00 to 19:00 but was paid for 8 hours.", payrollComparisonId: r1.comparison.id,
  });
  clock = ist("2026-03-03", "10:00");
  transitionCase(as(c.admin, oc, "employer_admin"), { caseId: case1.id, to: "triaged", note: "Reviewing attendance" });
  submitSafetyIncident(as(c.selvi, oc, "worker"), { category: "scaffolding", severity: "medium", description: "Loose plank on level 2 scaffold." });
  submitFeedback(as(c.selvi, oc, "worker"), { category: "workplace", body: "Rest breaks are often skipped on hot days.", anonymous: true });
  updateSkillPassport(as(c.supervisor, oc, "supervisor"), { workerId: c.karthik, skillId: c.skillElectrical, level: "intermediate", trainingRecordId: u(10, 1) });

  // College: Meena paid correctly; Rajesh short-paid on 10h.
  clock = ist("2026-03-02", "06:00");
  startShift(as(k.meena, ok, "worker"), {});
  startShift(as(k.rajesh, ok, "worker"), {});
  clock = ist("2026-03-02", "15:00");
  endShift(as(k.meena, ok, "worker"), {});
  clock = ist("2026-03-02", "16:00");
  endShift(as(k.rajesh, ok, "worker"), {});
  reconcileDay(as(k.admin, ok, "employer_admin"), { workerId: k.meena, date: "2026-03-02", amountPaid: 665, source: "employer_payroll" });
  const r2 = reconcileDay(as(k.admin, ok, "employer_admin"), { workerId: k.rajesh, date: "2026-03-02", amountPaid: 1000, source: "employer_payroll" });
  createFairnessCase(as(k.rajesh, ok, "worker"), {
    caseType: "wage_discrepancy", title: "Short payment on 2 March", payrollComparisonId: r2.comparison.id,
  });
  submitSafetyIncident(as(k.meena, ok, "worker"), { category: "slip_hazard", severity: "low", description: "Wet floor near canteen entrance." });
  updateSkillPassport(as(k.supervisor, ok, "supervisor"), { workerId: k.rajesh, skillId: k.skillPlumbing, level: "advanced", trainingRecordId: u(10, 2) });
  return db;
}

// Process-wide demo store (same pattern as src/lib/store.ts). NOT durable.
const g = globalThis as unknown as { __fsServerDb?: Db };
export const getDb = (): Db => (g.__fsServerDb ??= buildSeedDb());
export const resetDemoDb = () => (g.__fsServerDb = buildSeedDb());
